/**
 * File Name: provenance.ts
 * Purpose: Where a flow came from, and who touched it last (the user,
 *          2026-09-19: "we should have in flow if the flow was generated by an
 *          extension or a actual user ... and keep a track on what made
 *          changes last").
 *
 *          It matters once flows stop being only hand-drawn. A destination
 *          added from a form is a flow an extension's preset built; the
 *          operator who added it may never have opened the builder. So an
 *          operator looking at the list needs to know which flows are theirs,
 *          which arrived with a pack, and which of those a person has since
 *          changed - because that last group is the one a pack's own future
 *          changes must not quietly overwrite.
 *
 *          Derived, not stored: it reads `source`, `createdAt` and `updatedAt`
 *          off the record, so it cannot drift from them, and an older flow
 *          that has none of the new fields is honestly "unknown" rather than
 *          wrongly attributed.
 *
 * Author: Raghunath J
 * License: MIT
 */

/** Who made a change: a person, or code acting on its own. */
export type FlowActorKind = 'member' | 'extension' | 'system'

export interface FlowOrigin {
  /**
   * `preset`: an extension's preset built it (a form's destination).
   * `person`: somebody drew it, from scratch or from a template.
   * `unknown`: a flow saved before any of this was recorded.
   */
  kind: 'preset' | 'person' | 'unknown'
  /** The pack whose preset built it. */
  extensionId?: string
  /** Which preset, so two destinations of the same pack are distinguishable. */
  presetId?: string
  /** What it was added to, `form:frm_1`. */
  scope?: string
  /** The KIND of thing it was added to (`form`) - what the operator did. */
  scopeKind?: string
  /** The one it was added to (`frm_1`). */
  scopeId?: string
  /**
   * A person has edited it since it was created. Only ever true for a preset
   * flow, because a hand-drawn flow is edited by definition - and this is the
   * fact that says "do not assume the pack's shape here any more".
   */
  editedSince: boolean
  /** Who changed it last, as far as the record knows. */
  lastEditedBy: { kind: FlowActorKind; id: string | null } | null
  /** When, ISO. */
  lastEditedAt: string | null
}

const iso = (v: unknown): string | null => (typeof v === 'string' && v !== '' ? v : null)

/** The provenance of one stored flow. Pure, and safe on a record from any era. */
export function flowOrigin(flow: unknown): FlowOrigin {
  const f = (flow ?? {}) as Record<string, unknown>
  const source = f.source as { extensionId?: unknown; presetId?: unknown; scope?: unknown } | undefined
  const createdAt = iso(f.createdAt)
  const updatedAt = iso(f.updatedAt)
  const editedBy = f.editedBy as { kind?: unknown; id?: unknown } | undefined

  // Who last changed it. `editedBy` is what a write stamps now; `updatedBy`
  // is what every flow written before it has, and that was always a member.
  const lastEditedBy = editedBy && typeof editedBy.kind === 'string'
    ? { kind: editedBy.kind as FlowActorKind, id: typeof editedBy.id === 'string' ? editedBy.id : null }
    : typeof f.updatedBy === 'string' && f.updatedBy !== ''
      ? { kind: 'member' as const, id: f.updatedBy }
      : null

  if (source && typeof source.extensionId === 'string' && typeof source.presetId === 'string') {
    return {
      kind: 'preset',
      extensionId: source.extensionId,
      presetId: source.presetId,
      ...(typeof source.scope === 'string' ? {
        scope: source.scope,
        // `form:frm_1` -> the kind an operator recognises, and the one they
        // added it to. Split here so no surface has to parse it again.
        ...(source.scope.includes(':') ? {
          scopeKind: source.scope.slice(0, source.scope.indexOf(':')),
          scopeId: source.scope.slice(source.scope.indexOf(':') + 1),
        } : {}),
      } : {}),
      // A preset writes both stamps in the same instant, so anything later is
      // somebody's edit. Without a createdAt (a flow from before this) no
      // claim is made rather than a wrong one.
      editedSince: Boolean(createdAt && updatedAt && Date.parse(updatedAt) > Date.parse(createdAt)),
      lastEditedBy,
      lastEditedAt: updatedAt,
    }
  }

  return {
    kind: createdAt || lastEditedBy ? 'person' : 'unknown',
    editedSince: false,
    lastEditedBy,
    lastEditedAt: updatedAt,
  }
}

/**
 * What an operator reads, as a short label plus the full story on hover.
 *
 * The label answers "what IS this", and for a flow added to something that is
 * what the operator DID: they added a destination to a form, so the label says
 * "Form destination". The pack that contributed the preset is a second fact,
 * not the headline - seeing "Google" against a flow a form created was
 * confusing (the user, 2026-09-19), because Google supplied the recipe, the
 * form is where it was put to use.
 *
 * `you` is the member reading the list. Naming OTHER members would mean
 * reading the members table, which `manage:flows` does not grant - so the
 * story says when a change happened rather than inventing a who.
 */
export function originBadge(
  origin: FlowOrigin,
  opts: { extensionName?: (id: string) => string | undefined; you?: string | null } = {},
): { label: string; detail: string; edited: boolean } {
  const pack = (origin.extensionId && opts.extensionName?.(origin.extensionId)) || origin.extensionId
  const who = origin.lastEditedBy
  const byYou = who?.kind === 'member' && opts.you && who.id === opts.you
  const editor = who === null
    ? null
    : who.kind === 'extension'
      ? (opts.extensionName?.(who.id ?? '') ?? who.id ?? 'an extension')
      : who.kind === 'system'
        ? 'Tangen'
        : byYou ? 'you' : null           // another member is not named
  const when = origin.lastEditedAt ? new Date(origin.lastEditedAt).toLocaleString() : null
  const lastLine = who === null
    ? ''
    : editor
      ? ` Last changed by ${editor}${when ? ` on ${when}` : ''}.`
      : ` Last changed${when ? ` on ${when}` : ''}.`

  if (origin.kind === 'preset') {
    const where = origin.scopeKind ? `${origin.scopeKind.charAt(0).toUpperCase()}${origin.scopeKind.slice(1)} destination` : 'Added by an extension'
    const scope = origin.scopeId ? ` (${origin.scopeId})` : ''
    return {
      label: where,
      detail: `Built by ${pack} from its "${origin.presetId}" preset${origin.scopeKind ? `, for one ${origin.scopeKind}${scope}` : ''}.`
        + (origin.editedSince ? ' Someone has edited it since, so it is no longer the shape the preset built.' : '')
        + lastLine,
      edited: origin.editedSince,
    }
  }
  if (origin.kind === 'person') {
    return { label: 'Built here', detail: `Drawn in this workspace.${lastLine}`, edited: false }
  }
  return { label: 'Unknown', detail: 'This flow was saved before Tangen recorded where a flow came from.', edited: false }
}
